import{_ as s,o as a,c as t,ag as n}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"fr/nay-lib/permissions.md","filePath":"fr/nay-lib/permissions.md"}'),o={name:"fr/nay-lib/permissions.md"};function r(c,e,d,i,l,p){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><p>Chaque action Nayretis qui demande des droits vérifie un <strong>scope</strong>. Vous accordez les scopes par ACE, par des règles enregistrées dans la base, ou depuis l&#39;onglet Permissions de <code>/nay</code>.</p><h2 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Donne</th></tr></thead><tbody><tr><td><code>nay.admin</code></td><td>Tout : chaque script, les réglages Nayretis, les permissions, les jetons d&#39;API, les webhooks et le journal.</td></tr><tr><td><code>nay.config</code></td><td>Les réglages de tous les scripts.</td></tr><tr><td><code>nay.audit</code></td><td>Le journal.</td></tr><tr><td><code>&lt;resource&gt;.config</code></td><td>Les réglages d&#39;un script, par exemple <code>nay_car_wash.config</code>.</td></tr><tr><td><code>&lt;resource&gt;.&lt;name&gt;</code></td><td>Une permission déclarée par un script, listée sur sa page.</td></tr><tr><td><code>&lt;resource&gt;.*</code></td><td>Tous les scopes d&#39;un script. Fonctionne avec les règles (<code>nay_grant</code>), pas avec l&#39;ACE.</td></tr></tbody></table><h2 id="par-ace" tabindex="-1">Par ACE <a class="header-anchor" href="#par-ace" aria-label="Permalink to &quot;Par ACE&quot;">​</a></h2><p>Une ACE sur un scope l&#39;accorde. Accordez chaque scope par son nom complet (les scopes génériques comme <code>nay_car_wash.*</code> ne fonctionnent qu&#39;en règle). Dans <code>server.cfg</code> :</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span>
<span class="line"><span>add_ace group.mod nay_car_wash.config allow</span></span></code></pre></div><h2 id="par-regles" tabindex="-1">Par règles <a class="header-anchor" href="#par-regles" aria-label="Permalink to &quot;Par règles&quot;">​</a></h2><p>Les règles sont enregistrées dans la base et peuvent viser un joueur directement. Une règle a un type, un identifiant et un scope. Les types sont :</p><ul><li><code>ace</code> : chaque joueur autorisé sur cet objet ACE ;</li><li><code>discord</code>, <code>steam</code>, <code>fivem</code>, <code>license</code> : un joueur, par identifiant.</li></ul><p>Depuis la console du serveur :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license 1a2b3c4d5e6f nay.admin</span></span>
<span class="line"><span>nay_grant discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_revoke discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_rules</span></span></code></pre></div><p><code>nay_grant</code> et <code>nay_revoke</code> prennent <code>&lt;ace|discord|steam|fivem|license&gt; &lt;identifier&gt; &lt;scope&gt;</code>. <code>nay_rules</code> liste toutes les règles avec leur numéro.</p><p>En jeu, l&#39;onglet <strong>Permissions</strong> de <code>/nay</code> (scope <code>nay.admin</code>) liste, ajoute et retire les mêmes règles. Chaque changement est écrit dans le <a href="/fr/nay-lib/audit">journal</a>.</p>`,14)])])}const h=s(o,[["render",r]]);export{g as __pageData,h as default};
